다음 C 프로그램의 실행 결과는?

#include <stdio.h>
int f(int *i, int j) {
     *i += 5;
     return(2 * *i + ++j);
}
int main(void) {
     int x=10, y=20;

     printf("%d ", f(&x, y));
     printf("%d %d\n", x, y);
}

다음 C 프로그램의 실행 결과는?

#include <stdio.h>
void main() {
     int a, b;
     a = 2;
     while (a-- > 0)
            printf("a = %d＼n", a);
     for (b = 0; b< 2; b++)
            printf("a = %d＼n", a++);
}
